use serde::{Deserialize,Serialize};
use serde_json::{json,Value};
use std::collections::BTreeSet;
use thiserror::Error;
pub const BOUNDARY:&str=PRECLINICAL_BOUNDARY;pub const CONTENT_TYPE:&str="application/vnd.aurora.stewardship.snapshot-integrity-card-1+json";
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq,Eq)] pub struct StewardshipItem4{pub item_id:String,pub owner:String,pub lifecycle:String,pub checksum:String,pub evidence_state:String,pub reviewer:String,pub retention_epoch:u64,pub negative_result:bool,pub local:bool,pub aggregate_only:bool}
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq,Eq)] pub struct SnapshotIntegrityRequest4{pub schema_version:String,pub request_id:String,pub purpose:String,pub snapshot_id:String,pub quarter:String,pub items:Vec<StewardshipItem4>,pub required_item_order:Vec<String>,pub current_epoch:u64,pub minimum_retention_epoch:u64,pub signed_manifest:bool,pub independent_review:bool,pub policy_allowed:bool,pub protected_closure:bool,pub raw_data_local:bool,pub aggregate_only:bool,pub replay_identity:String,pub adversarial_events:Vec<String>,pub item_budget:usize,pub boundary:String}
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq,Eq)] pub struct SnapshotIntegrityArtifact4{pub artifact_id:String,pub content_type:String,pub content_hash:String,pub semantic_loss:Vec<String>,pub evidence_digests:Vec<String>,pub boundary:String}
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq,Eq)] pub struct SnapshotIntegrityCard7{pub schema_version:String,pub contract_version:String,pub feature_id:String,pub request_id:String,pub purpose:String,pub snapshot_id:String,pub quarter:String,pub disposition:String,pub item_order:Vec<String>,pub accepted_order:Vec<String>,pub rejected_order:Vec<String>,pub unknown_order:Vec<String>,pub omitted_order:Vec<String>,pub owner_order:Vec<String>,pub reviewer_order:Vec<String>,pub retention_order:Vec<String>,pub negative_order:Vec<String>,pub checksum_order:Vec<String>,pub replay_identity:String,pub closure_digest:String,pub raw_data_local:bool,pub aggregate_only:bool,pub boundary:String,pub effect_receipts:Vec<String>,pub artifact:SnapshotIntegrityArtifact4}
#[derive(Debug,Error)] pub enum SnapshotIntegrityError{#[error("snapshot integrity input is invalid: {0}")] Invalid(String),#[error("snapshot integrity digest failed: {0}")] Digest(String)}
fn digest(v:&str)->bool{v.len()==64&&v.bytes().all(|b|b.is_ascii_hexdigit())}fn canonical(v:&[String])->bool{v.windows(2).all(|w|w[0]<w[1])}fn invalid(v:impl Into<String>)->SnapshotIntegrityError{SnapshotIntegrityError::Invalid(v.into())}
pub fn manifest(feature_id:&str,contract_version:&str,scale:&str,mode:&str)->Value{json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"capability_id":feature_id,"version":contract_version,"owner_crate":"stewardship","consumers":["release steward","consortium archivist","review board","research workbench"],"behavior":format!("qualify immutable research snapshots at {scale} ({mode})"),"value":"prevents unsigned, prematurely retired, unreviewed, or negative-result-suppressed snapshots from release","input_schema":"SnapshotIntegrityRequest4@1","output_schema":"SnapshotIntegrityCard7@1","effects":["emit:snapshot-card","retain:negative-finding","block:unsafe-snapshot"],"permissions":["read:local-manifest"],"determinism":"byte_stable","autonomy_tier":"A1","boundary":BOUNDARY})}
fn validate_card(c:&SnapshotIntegrityCard7)->Result<(),SnapshotIntegrityError>{if c.schema_version!=RESEARCH_CONTRACT_SCHEMA_VERSION||c.feature_id.is_empty()||c.snapshot_id.is_empty()||c.quarter.is_empty()||c.boundary!=BOUNDARY||c.artifact.boundary!=BOUNDARY||!c.raw_data_local||!c.aggregate_only||!digest(&c.replay_identity)||!digest(&c.closure_digest)||c.artifact.content_type!=CONTENT_TYPE||c.artifact.content_hash!=c.closure_digest{return Err(invalid("snapshot identity, locality, artifact, digest, or boundary is incomplete"));}for v in [&c.item_order,&c.accepted_order,&c.rejected_order,&c.unknown_order,&c.omitted_order,&c.owner_order,&c.reviewer_order,&c.retention_order,&c.negative_order,&c.checksum_order,&c.effect_receipts]{if !canonical(v){return Err(invalid("snapshot vectors are not canonical"));}}let ids=c.item_order.iter().collect::<BTreeSet<_>>();let states=c.accepted_order.iter().chain(&c.rejected_order).chain(&c.unknown_order).chain(&c.omitted_order).collect::<Vec<_>>();if states.len()!=ids.len()||states.into_iter().collect::<BTreeSet<_>>()!=ids{return Err(invalid("item states do not partition items"));}Ok(())}
pub fn qualify(q:&SnapshotIntegrityRequest4,feature_id:&str,contract_version:&str,scale:&str,mode:&str)->Result<SnapshotIntegrityCard7,SnapshotIntegrityError>{if q.schema_version!=RESEARCH_CONTRACT_SCHEMA_VERSION||q.request_id.trim().is_empty()||q.purpose.trim().is_empty()||q.snapshot_id.trim().is_empty()||q.quarter.trim().is_empty()||q.items.is_empty()||q.required_item_order.is_empty()||!canonical(&q.required_item_order)||!digest(&q.replay_identity)||q.boundary!=BOUNDARY||!q.raw_data_local||!q.aggregate_only||!canonical(&q.adversarial_events)||q.item_budget==0{return Err(invalid("snapshot identity, ordering, digest, locality, boundary, or budget is invalid"));}let mut rows=q.items.clone();rows.sort_by(|a,b|a.item_id.cmp(&b.item_id));let mut seen=BTreeSet::new();let mut accepted=BTreeSet::new();let mut rejected=BTreeSet::new();let mut unknown=BTreeSet::new();let mut omitted=BTreeSet::new();let mut owners=BTreeSet::new();let mut reviewers=BTreeSet::new();let mut retention=BTreeSet::new();let mut negative=BTreeSet::new();let mut checksums=BTreeSet::new();let mut evidence=BTreeSet::new();for i in &rows{if i.item_id.trim().is_empty()||!seen.insert(i.item_id.clone())||i.owner.trim().is_empty()||i.lifecycle.trim().is_empty()||!digest(&i.checksum)||i.evidence_state.trim().is_empty()||i.reviewer.trim().is_empty()||!i.local||!i.aggregate_only{return Err(invalid("item identity, checksum, reviewer, evidence, or locality is invalid"));}owners.insert(format!("{}:{}",i.item_id,i.owner));reviewers.insert(format!("{}:{}",i.item_id,i.reviewer));retention.insert(format!("{}:{}",i.item_id,i.retention_epoch));checksums.insert(format!("{}:{}",i.item_id,i.checksum));evidence.insert(i.checksum.clone());if i.negative_result{negative.insert(format!("{}:negative-result",i.item_id));}if i.evidence_state=="unknown"||i.checksum==q.replay_identity{unknown.insert(i.item_id.clone());}else if i.lifecycle=="retired"||i.retention_epoch<q.minimum_retention_epoch||i.reviewer==i.owner||i.reviewer=="unverified"{rejected.insert(i.item_id.clone());}else if !q.required_item_order.contains(&i.item_id){omitted.insert(i.item_id.clone());}else{accepted.insert(i.item_id.clone());}}let missing=q.required_item_order.iter().filter(|x|!seen.contains(*x)).cloned().collect::<Vec<_>>();let global=!q.policy_allowed||!q.protected_closure||!q.signed_manifest||!q.independent_review||!q.raw_data_local||!q.aggregate_only||!q.adversarial_events.is_empty()||rows.len()>q.item_budget;if global{omitted.extend(seen.iter().cloned());accepted.clear();rejected.clear();unknown.clear();}let disposition=if global{"blocked"}else if !missing.is_empty()||!unknown.is_empty(){"unknown"}else if !rejected.is_empty()||!omitted.is_empty(){"partial"}else{"qualified"};let item_order=seen.iter().cloned().collect::<Vec<_>>();let accepted_order=accepted.into_iter().collect::<Vec<_>>();let rejected_order=rejected.into_iter().collect::<Vec<_>>();let unknown_order=unknown.into_iter().collect::<Vec<_>>();let omitted_order=omitted.into_iter().collect::<Vec<_>>();let body=json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"contract_version":contract_version,"feature_id":feature_id,"request_id":q.request_id,"purpose":q.purpose,"snapshot_id":q.snapshot_id,"quarter":q.quarter,"disposition":disposition,"item_order":item_order,"accepted_order":accepted_order,"rejected_order":rejected_order,"unknown_order":unknown_order,"omitted_order":omitted_order,"owner_order":owners.into_iter().collect::<Vec<_>>(),"reviewer_order":reviewers.into_iter().collect::<Vec<_>>(),"retention_order":retention.into_iter().collect::<Vec<_>>(),"negative_order":negative.into_iter().collect::<Vec<_>>(),"checksum_order":checksums.into_iter().collect::<Vec<_>>(),"replay_identity":q.replay_identity,"raw_data_local":true,"aggregate_only":true,"boundary":BOUNDARY});let closure_digest=ContentHash::of_value(&body).map_err(|e|SnapshotIntegrityError::Digest(e.to_string()))?.to_string();let effect_receipts=if disposition=="qualified"{vec![format!("approve:snapshot:{}",q.snapshot_id)]}else{vec!["block:unsafe-snapshot".into()]};let artifact=SnapshotIntegrityArtifact4{artifact_id:format!("stewardship-snapshot:{}",q.snapshot_id),content_type:CONTENT_TYPE.into(),content_hash:closure_digest.clone(),semantic_loss:body["omitted_order"].as_array().unwrap().iter().filter_map(Value::as_str).map(str::to_owned).collect(),evidence_digests:evidence.into_iter().collect(),boundary:BOUNDARY.into()};let c=SnapshotIntegrityCard7{schema_version:RESEARCH_CONTRACT_SCHEMA_VERSION.into(),contract_version:contract_version.into(),feature_id:feature_id.into(),request_id:q.request_id.clone(),purpose:q.purpose.clone(),snapshot_id:q.snapshot_id.clone(),quarter:q.quarter.clone(),disposition:disposition.into(),item_order:body["item_order"].as_array().unwrap().iter().filter_map(Value::as_str).map(str::to_owned).collect(),accepted_order,rejected_order,unknown_order,omitted_order,owner_order:body["owner_order"].as_array().unwrap().iter().filter_map(Value::as_str).map(str::to_owned).collect(),reviewer_order:body["reviewer_order"].as_array().unwrap().iter().filter_map(Value::as_str).map(str::to_owned).collect(),retention_order:body["retention_order"].as_array().unwrap().iter().filter_map(Value::as_str).map(str::to_owned).collect(),negative_order:body["negative_order"].as_array().unwrap().iter().filter_map(Value::as_str).map(str::to_owned).collect(),checksum_order:body["checksum_order"].as_array().unwrap().iter().filter_map(Value::as_str).map(str::to_owned).collect(),replay_identity:q.replay_identity.clone(),closure_digest,raw_data_local:true,aggregate_only:true,boundary:BOUNDARY.into(),effect_receipts,artifact};let _=(scale,mode);validate_card(&c)?;Ok(c)}
